 static StringBuilder text=new StringBuilder(),names=new StringBuilder();static void add(String kind,int id,String s){if(s!=null&&!s.isBlank()&&!s.equals("null"))text.append(kind).append("|").append(id).append("|").append(Base64.getEncoder().encodeToString(s.getBytes(java.nio.charset.StandardCharsets.UTF_8))).append("\n");}static void name(String s){if(s!=null&&!s.isBlank()&&!s.equals("null"))names.append(Base64.getEncoder().encodeToString(s.getBytes(java.nio.charset.StandardCharsets.UTF_8))).append("\n");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Path out=Path.of(a[0]);Client.main(new String[0]);for(int i=0;i<1200&&(Client.instance==null||!Client.instance.soloStartupComplete);i++)Thread.sleep(100);if(Client.instance==null||!Client.instance.soloStartupComplete)throw new AssertionError("Startup timeout");int skipped=0;for(int id=0;id<ItemDefinition.totalItems;id++){try{ItemDefinition d=ItemDefinition.forID(id);name(d.name);add("item-examine",id,d.description);if(d.inventoryOptions!=null)for(String s:d.inventoryOptions)add("item-action",id,s);}catch(RuntimeException e){skipped++;}}for(int id=0;id<NpcDefinition.totalAmount;id++){try{NpcDefinition d=NpcDefinition.forID(id);name(d.name);add("npc-examine",id,d.description);if(d.actions!=null)for(String s:d.actions)add("npc-action",id,s);}catch(RuntimeException e){skipped++;}}for(int id=0;id<RSInterface.interfaceCache.length;id++){RSInterface d=RSInterface.interfaceCache[id];if(d==null)continue;add("interface",id,d.message);add("interface-enabled",id,d.messageEnabled);add("tooltip",id,d.tooltip);add("selected-action",id,d.selectedActionName);}Files.writeString(out.resolve("cache-visible-strings.txt"),text.toString());Files.writeString(out.resolve("cache-protected-names.txt"),names.toString());Files.writeString(out.resolve("cache-inventory-ready"),"READY skipped-unavailable-definitions="+skipped);javax.swing.SwingUtilities.invokeLater(()->ClientWindow.frame.dispatchEvent(new java.awt.event.WindowEvent(ClientWindow.frame,java.awt.event.WindowEvent.WINDOW_CLOSING)));}
